cases.cmd:
R={{FIX}}/kc-{{SID}}
mkdir -p $R/.claude/hooks $R/.claude/lib $R/scripts
cp {{KIT}}/hooks/handler-claude-md-check.sh $R/.claude/hooks/
cp {{KIT}}/lib/kit_config.py {{KIT}}/lib/kit_testtag.py $R/.claude/lib/
cp -R {{KIT}}/presets $R/.claude/
cp {{KIT}}/scripts/rules-coverage.py {{KIT}}/scripts/untagged-tests.py {{KIT}}/scripts/migrate-rm-traits.py $R/scripts/
printf '%s' '{"preset": "hexagonal", "testTag": {"framework": "junit"}}' > $R/.claude/kit.config.json
F=$R/src/application/CreateProduct
T=$R/src/test/java/catalog
mkdir -p $F $T
cat > $F/CreateProductUseCase.java <<'JEOF'
public final class CreateProductUseCase { }
JEOF
cat > $F/CLAUDE.md <<'MDEOF'
# CreateProduct — create a product

## Business rules <!-- kit:rules -->

<!-- kit:cols id,rule,outcome -->
| ID | Rule | Exception / Outcome |
|----|------|---------------------|
| RM-01 | The name is unique in the catalog | ProductNameAlreadyUsed |
| RM-02 | The catalog is open | CatalogClosed |

## Flow <!-- kit:flow -->

1. Load the catalog, create the product, save.

## Emitted events <!-- kit:events -->

- ProductCreated
MDEOF
cat > $T/CreateProductUseCaseTest.java <<'JEOF'
class CreateProductUseCaseTest {

    @Test
    @Tag("RM:CreateProduct/RM-01")
    void rejectsANameAlreadyUsed() {
    }

    @Tag("RM:CreateProduct/RM-02")
    @ParameterizedTest
    @ValueSource(ints = {1, 2})
    void rejectsAClosedCatalog(int n) {
    }

    @Test
    void carriesNoTag() {
    }
}
JEOF
python3 $R/scripts/rules-coverage.py | tr '\n' ' '

